solution:
def has_close_repeat(nums: list[int], k: int) -> bool:
    window = set()                       # the values at most k positions back
    for i, x in enumerate(nums):
        if x in window:
            return True
        window.add(x)
        if len(window) > k:              # the value k steps back leaves the window
            window.remove(nums[i - k])
    return False

